#include "motor_driver.h"

#define MOTOR_PWM_FREQ_HZ      (10000)   // 改成示例常用值
#define MOTOR_PWM_DUTY_MAX     (10000)

#define MOTOR_PWM_POS_CH       (PWM_P21_7)
#define MOTOR_PWM_NEG_CH       (PWM_P21_6)

static uint16 speed_to_duty_tick(int16 speed_permille)
{
    uint16 abs_speed;

    if (speed_permille < 0)
    {
        abs_speed = (uint16)(-speed_permille);
    }
    else
    {
        abs_speed = (uint16)speed_permille;
    }

    if (abs_speed > 1000)
    {
        abs_speed = 1000;
    }

    return (uint16)((uint32)abs_speed * MOTOR_PWM_DUTY_MAX / 1000U);
}

void motor_driver_init(void)
{
    pwm_init(MOTOR_PWM_POS_CH, MOTOR_PWM_FREQ_HZ, 0);
    pwm_init(MOTOR_PWM_NEG_CH, MOTOR_PWM_FREQ_HZ, 0);

    pwm_set_duty(MOTOR_PWM_POS_CH, 0);
    pwm_set_duty(MOTOR_PWM_NEG_CH, 0);
}

void motor_driver_set_speed(int16 speed_permille)
{
    uint16 duty = speed_to_duty_tick(speed_permille);

    if (speed_permille > 0)
    {
        pwm_set_duty(MOTOR_PWM_POS_CH, duty);
        pwm_set_duty(MOTOR_PWM_NEG_CH, 0);
    }
    else if (speed_permille < 0)
    {
        pwm_set_duty(MOTOR_PWM_POS_CH, 0);
        pwm_set_duty(MOTOR_PWM_NEG_CH, duty);
    }
    else
    {
        pwm_set_duty(MOTOR_PWM_POS_CH, 0);
        pwm_set_duty(MOTOR_PWM_NEG_CH, 0);
    }
}

